package com.edunexa.app.data
import com.google.firebase.firestore.FirebaseFirestore
class CouponRepository{private val db=FirebaseFirestore.getInstance();fun createCoupon(code:String,discount:Int,onResult:(Boolean,String)->Unit){val c=code.trim().uppercase();if(c.isBlank()||discount !in 1..100)return onResult(false,"Enter valid code and 1-100% discount");db.collection("coupons").document(c).set(Coupon(c,discount,true)).addOnSuccessListener{onResult(true,"$c created with $discount% discount")}.addOnFailureListener{onResult(false,it.message?:"Coupon creation failed")}}fun validateCoupon(code:String,onResult:(Coupon?)->Unit){db.collection("coupons").document(code.trim().uppercase()).get().addOnSuccessListener{d->val c=d.toObject(Coupon::class.java);onResult(if(c?.active==true)c else null)}.addOnFailureListener{onResult(null)}}fun all(onResult:(List<Coupon>)->Unit,onError:(String)->Unit){db.collection("coupons").get().addOnSuccessListener{s->onResult(s.documents.mapNotNull{it.toObject(Coupon::class.java)})}.addOnFailureListener{onError(it.message?:"Could not load coupons")}}fun setActive(code:String,active:Boolean,onResult:(Boolean,String)->Unit){db.collection("coupons").document(code).update("active",active).addOnSuccessListener{onResult(true,if(active)"Coupon activated" else "Coupon disabled")}.addOnFailureListener{onResult(false,it.message?:"Update failed")}}}
